//! 🧪️ Authored Draw geometry and independent serde witnesses retain fitting coverage after codec removal.
use super::*;
fn fixture()->serde_json::Value{serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap()}
fn target(v:&serde_json::Value)->LayoutBounds{LayoutBounds{x:v["x"].as_f64().unwrap(),y:v["y"].as_f64().unwrap(),width:v["width"].as_f64().unwrap(),height:v["height"].as_f64().unwrap(),rotation:v["rotation"].as_f64().unwrap()}}
fn bounds(v:&serde_json::Value)->Option<DrawingBounds>{if v.is_null(){None}else{Some(DrawingBounds{left:v["left"].as_f64().unwrap(),top:v["top"].as_f64().unwrap(),right:v["right"].as_f64().unwrap(),bottom:v["bottom"].as_f64().unwrap()})}}
fn near_affine(a:DrawingAffine,v:&serde_json::Value){for(n,key)in[(a.xx,"xx"),(a.xy,"xy"),(a.yx,"yx"),(a.yy,"yy"),(a.dx,"dx"),(a.dy,"dy")]{assert!((n-v[key].as_f64().unwrap()).abs()<1e-4)}}
#[test]
fn authored_geometry_fits_with_original_draw_text_extents(){for row in fixture()["cases"].as_array().unwrap(){let document:DrawingSnapshot=serde_json::from_value(row["content"].clone()).unwrap();let(mut owner,_)=RetainedCloneSource::admit_owned(document,(),g(grant())).unwrap_or_else(|_|panic!("original Draw owner"));let read=ChildAdmissionRead{source:semio_framework_io_ports::erase_child_admission_source(owner.borrow(),0x4348494c),admitter:&DRAWING_ADMITTER,vector:&DRAWING_VECTOR_SOURCE};let mut cursor=DrawingPlanCursor::new(DrawingSourceAddress::Document,DrawingPlacement::Content,target(&row["target"]));let mut kinds=Vec::new();let mut done=false;for _ in 0..10000{match cursor.advance(&read,grant()).unwrap(){DrawingPlanTurn::MeasureText(plan)=>{let measured=row["expected"]["textExtents"].as_array().unwrap().iter().find(|m|m["index"].as_u64().unwrap()as usize==plan.index).unwrap();assert_eq!(plan.content.text_chunk(0),measured["content"].as_str());assert_eq!(plan.font.family,"shareTechMono");assert_eq!(plan.font.size,11.0);cursor.include_text_extent(plan.index,bounds(&measured["bounds"])).unwrap()},DrawingPlanTurn::Fitted{bounds:actual,affine}=>{let expected=bounds(&row["expected"]["bounds"]);assert_eq!(actual.is_some(),expected.is_some());if let(Some(a),Some(b))=(actual,expected){for(left,right)in[(a.left,b.left),(a.top,b.top),(a.right,b.right),(a.bottom,b.bottom)]{assert!((left-right).abs()<1e-4)}}near_affine(affine,&row["expected"]["affine"])},DrawingPlanTurn::Primitive(p)=>kinds.push(match p{DrawingPrimitive::BeginPath{..}=>"beginPath",DrawingPrimitive::Segment{..}=>"segment",DrawingPrimitive::EndPath{..}=>"endPath",DrawingPrimitive::Text(_)=>"text",DrawingPrimitive::Resolve{..}=>"resolve"}),DrawingPlanTurn::Done=>{done=true;break},_=>{}}}assert!(done);let expected:Vec<&str>=row["expected"]["primitiveKinds"].as_array().unwrap().iter().map(|v|v.as_str().unwrap()).collect();assert_eq!(kinds,expected);close(&mut cursor);drop(cursor);while !owner.terminal_is_empty(){owner.close_step(g(grant())).unwrap();}}}
#[path="📄️page-canvas/🦀️.rs"]mod page_canvas;
